from django.db import migrations

 
def asignar_roles(apps, schema_editor):
    """Los tipos que ya existían reciben el rol que tenían implícito por su nombre."""
    TipoUsuario = apps.get_model("usuarios", "TipoUsuario")
    for tipo in TipoUsuario.objects.all():
        nombre = tipo.nombre.strip().lower()
        if nombre == "administrador":
            rol = "administrador"
        elif "personal" in nombre:
            rol = "personal"
        elif nombre in ("docente", "estudiante", "funcionario"):
            rol = "universitario"
        else:
            rol = "externo"
        tipo.rol = rol
        tipo.save(update_fields=["rol"])
 
 
